//! The After Effects SDK bindings this crate is built against, with one type
//! per enum constant on every OS.
//!
//! [`PluginEntryPoint`](crate::PluginEntryPoint), [`Layer::as_sys`](crate::Layer::as_sys)
//! and the `From` conversions on [`Pixel`](crate::Pixel) use these types, so name
//! them through this path to get exactly the version aexlo uses. A breaking
//! release of `after-effects-sys` is a breaking release of aexlo.
//!
//! `after-effects-sys` is generated by bindgen, which types the SDK's anonymous
//! enum constants by the host C++ compiler's enum representation: `i32` on
//! Windows, but `u32` on macOS and Linux for every enum without a negative
//! value (the `PF_Err` family and `A_long` typedefs they feed are `i32` on both).
//! Code written against the raw constants therefore compiled on one OS and
//! needed a cast on the other.
//!
//! This module re-exports the whole crate, then shadows each constant aexlo
//! uses with a copy typed as the SDK typedef of its enum (`PF_Err_NONE` is a
//! `PF_Err`, `PF_Cmd_RENDER` a `PF_Cmd`, ...). The typedefs are the same on
//! every OS, so the constants are too. The enums whose typedef itself differs
//! per OS (`PF_ExtendedSuiteTool`, `PF_SuiteTool`, `PF_Step`) have `A_long`
//! constants.
//!
//! Types the SDK itself declares per OS are not changed: `PrPixelFormat`,
//! `PF_FontStyleSheet` and the three typedefs above are `u32` or `i8` on macOS
//! and `i32` on Windows, so convert values of those types before comparing
//! them with a constant.
//!
//! A constant not listed below still has the platform-dependent type of
//! `after-effects-sys`: inside aexlo, when the first use of a new one needs a
//! cast on one OS only, add it to the group of its typedef here instead of
//! casting at the call site.

// Each copy casts to its typedef, which is the identity on whichever OS already
// agrees. This is the only place that casts.
#![allow(clippy::unnecessary_cast)]

pub use after_effects_sys::*;

/// An SDK enum value of the integer type `after-effects-sys` gives its typedef,
/// as the `A_long` every OS agrees on.
///
/// `PF_ExtendedSuiteTool`, `PF_SuiteTool`, `PF_Step` and `PF_FontStyleSheet` are
/// `i8` on macOS but `i32` on Windows, and `PrPixelFormat` is `u32` / `i32`, so
/// a callback parameter of those types cannot be fixed by retyping a constant
/// and the matching `as` would be redundant on one OS.
pub(crate) trait AsLong {
	/// `self` as an `A_long`.
	fn long(self) -> A_long;
}

macro_rules! as_long {
	($($t:ty),*) => {$(
		impl AsLong for $t {
			fn long(self) -> A_long {
				self as A_long
			}
		}
	)*};
}

as_long!(i8, u8, i32, u32);

/// A `PrPixelFormat` as the FourCC `u32` aexlo stores.
pub(crate) const fn fourcc(format: PrPixelFormat) -> u32 {
	format as u32
}

macro_rules! typed_consts {
	($($ty:ident { $($name:ident),* $(,)? })*) => {
		$($(
			#[doc = concat!("`", stringify!($name), "`, typed as `", stringify!($ty), "` on every OS.")]
			#[allow(non_upper_case_globals)]
			pub const $name: $ty = after_effects_sys::$name as $ty;
		)*)*
	};
}

